/**
 * 拆分单行食材文本为 [纯食材名称, 数量部分]
 * 例如:
 * "番茄 2个" -> { name: "番茄", amount: "2个" }
 * "鸡蛋" -> { name: "鸡蛋", amount: "" }
 */
export function splitIngredientLine(line: string): { name: string; amount: string } {
  if (!line || typeof line !== 'string') return { name: '', amount: '' };
  const trimmed = line.trim();
  if (!trimmed) return { name: '', amount: '' };

  const spaceMatch = trimmed.match(/^(\S+)\s+(.+)$/);
  if (spaceMatch) {
    return { name: spaceMatch[1].trim(), amount: spaceMatch[2].trim() };
  }

  const amountMatch = trimmed.match(/^(.*?)([\d\.]+\s*(?:g|克|kg|公斤|斤|两|个|根|块|颗|只|条|片|瓣|包|碗|盒|头)|适量|少许|若干|适度|随量)$/i);
  if (amountMatch && amountMatch[1].trim()) {
    return { name: amountMatch[1].trim(), amount: amountMatch[2].trim() };
  }

  return { name: trimmed, amount: '' };
}

/**
 * 纠偏单行食材文本中的别名 (全词绝对匹配 Exact Match)
 * 提取纯食材名称进行绝对相等比对 (if pureName === alias)，避免部分子串误伤 (如"鸡蛋"误判为"鸡肉蛋")
 * 例如: "番茄 2个" -> "西红柿 2个", "鸡蛋 2个" -> "鸡蛋 2个"
 */
export function correctIngredientLine(line: string, aliasMap: Record<string, string> = STATIC_ALIAS_MAP): string {
  if (!line || typeof line !== 'string') return '';
  const trimmed = line.trim();
  if (!trimmed) return '';

  const { name, amount } = splitIngredientLine(trimmed);
  if (!name) return trimmed;

  // 绝对相等全词匹配
  const stdName = aliasMap[name];
  if (stdName && stdName !== name) {
    return amount ? `${stdName} ${amount}` : stdName;
  }

  return trimmed;
}

/**
 * 纠偏多行食材文本
 */
export function correctIngredientsText(text: string, aliasMap: Record<string, string> = STATIC_ALIAS_MAP): string {
  if (!text || typeof text !== 'string') return '';
  const lines = text.split(/\r?\n/);
  const correctedLines = lines.map((line) => correctIngredientLine(line, aliasMap));
  return correctedLines.join('\n');
}
